{"script": "find log_files -type f -name 'log_server_*_*.txt' | while read -r file; do
  server_id=$(echo "$file" | grep -o ".*log_server_\([0-9]\+\)_" | grep -o ".*\1" | tr -d '_');
  file_date=$(echo "$file" | grep -o "_\([0-9]\{4\}-\([0-9]\{2\}-\([0-9]\{2\}\)\)" | tr -d '_');
  current_date=$(date -d "7 days ago" +"%Y-%m-%d");
  if [[ $server_id -gt 1 && $(echo "$server_id" | awk '{for(i=2;i*i<=$1;i++) if($1%i==0) exit 1) print 0} END {print 1}') -eq 1 && "$file_date" -ge "$current_date" ]]; then
    sum=$(awk '{s+=$1} END {print s}' "$file");
    total=$((total + sum));
  fi;
done
echo $total"}

