from datetime import datetime

def main():
    parser = argparse.ArgumentParser(description='Format a date string.')
    parser.add_argument('date', help='The input date string.')
    parser.add_argument('format', help='The format string.')
    args = parser.parse_args()

    try:
        parsed_date = datetime.strptime(args.date, '%Y-%m-%d')
        formatted_date = parsed_date.strftime(args.format)
        print(formatted_date)
    except ValueError as e:
        print(f"Error: {e}")

if __name__ == '__main__':
    main()"}
